        def tc(k): wa("j2", WS[k][0]); J("jldi j3, %d" % len(WS[k][1]), "jcall bz_tadd")
        o("bu_wcount:                      ; WHERE A CONVERSATION GOES ON (the Capitan, 2026-11-22: \"que aprenda de los libros que ya")
        o("                                ; leyo: eso es una conversacion gigante gratis\"; Razar's curiosity, D69 and D50: by how much")
        o("                                ; it adds, not by volume). Every line of her house answers the one before it. For every")
        o("                                ; word, as she goes through her house each time she is born: in how many lines it is, and")
        o("                                ; in how many of them the line before had it too (the talk went on by it). Her talks with")
        o("                                ; him are lines of her house too (\"dialogo\"): what he answers counts the same. j4 = its")
        o("                                ; print, kept. A slot: print, lines, lines it went on, the last line it was in. The table")
        o("                                ; grows as it fills (twice its slots when half are used)")
        o("  ; (the word before it in its line: of how many different words it came after, its cases)")
