        o("fr_c_d:")
        inc(FM); J("jldi j10, 2", "jsub j10, j1, j10", "jjnz j10, fr_m")
        o("  ; every passage kept apart, of each book: whose it is")
        li("j0", B + FRES); J("jst j14, j0, 0", "jst j14, j0, 8", "jst j14, j0, 16", "jst j14, j0, 24"); gs("j14", FS)
