        J("jldi j1, 4", "jldi j2, 6", "jldi j5, 0", "jldi j7, 1"); gl("j3", NMROOM); J("jldi j4, 14", "jcall r_txt")
        gl("j3", NMROOM); J("jldi j10, 64", "jadd j3, j3, j10"); gl("j4", NMLEN); J("jldi j1, 4", "jldi j2, 18", "jldi j5, 0", "jldi j7, 1", "jcall r_txt")
        o("  ; (the cursor: a line under where the next letter goes)")
