    def dialogo_routines():
        assert NM0 + 48 <= 0x1D80
        if g.get("PANEL"):              # her panel's lines: 9 cells each (her 7-dot letters and two of air), from 2 cells in
            PY, PH, PW, _ = g["PANEL"]  # on the left her words, then what is typed (its cursor below it); on the right
            PNR = (PH - 9) // 9 + 1     # her thoughts. 52 letters fit a half (316 cells, 6 each)
            SHOWN = PNR - 4             # (then two lines for her last thought, then what is typed)
        else:
            SHOWN = 8
        def dl(r, off): gl("j6", DLR); J("jld %s, j6, %d" % (r, off))
        def ds(r, off): gl("j6", DLR); J("jst %s, j6, %d" % (r, off))
        def da(r, off):                 # (j15 is free outside a request: j10 often holds the request being made)
            gl(r, DLR); J("jldi j15, %d" % off, "jadd %s, %s, j15" % (r, r))
        def dinc(off): dl("j1", off); J("jldi j10, 1", "jadd j1, j1, j10"); ds("j1", off)
        def dtext(off, t):
            gl("j6", DLR)
            for i, ch in enumerate(t):
                J("jldi j10, %d" % ch, "jstb j10, j6, %d" % (off + i))
        o("r_dlg_save:                     ; her counts into \"charla\"")
        J("jcall r_cable_flush            ; (and her new living cables, if any)")
        J("jcall r_gustos_save            ; (and her tastes)")
        da("j11", D_LBL + 16); J("jldi j10, 12", "jldi j12, 6", "jcall r_tocar"); da("j11", D_LBL + 16); J("jldi j12, 6", "jcall r_open"); ld("j9", "FH"); J("jjn j9, dsv_r")
        J("jldi j10, 6"); da("j11", D_NC); J("jldi j12, 32", "jcall r_file", "jldi j10, 6"); da("j11", D_MC); J("jldi j12, 32", "jcall r_file", "jldi j10, 6"); da("j11", D_BN0); J("jldi j12, 48", "jcall r_file", "jldi j10, 6"); da("j11", D_PM); J("jldi j12, %d" % (48 + 2048 + 96), "jcall r_file", "jldi j10, 7", "jcall r_file")
        o("dsv_r:")
        J("jret")
        o("r_dlg_load:                     ; HER WORD: its room, its labels, her counts")
        li("j1", D_ROOM); J("jcall r_alloc"); gs("j0", DLR); J("jadd j6, j0, j14", "jldi j2, %d" % (D_ROOM // 8))
        o("dll_z:")
        J("jst j14, j6, 0", "jldi j10, 8", "jadd j6, j6, j10", "jldi j10, 1", "jsub j2, j2, j10", "jjnz j2, dll_z")
        dtext(D_LBL, b"dialogo"); dtext(D_LBL + 16, b"charla"); dtext(D_LBL + 32, b"letras"); dtext(D_LBL + 48, b"abecedario")
        dtext(D_LBL + 64, b"rodeos"); dtext(D_LBL + 80, b"preguntas-mias"); dtext(D_LBL + 96, b"libro-preguntas"); dtext(D_LBL + 112, b"preguntas-viejas"); dtext(D_LBL + 128, b"arbol"); dtext(D_LBL + 144, b"charla-libros")
        da("j11", D_LBL + 16); J("jldi j12, 6", "jcall r_open"); ld("j9", "FH"); J("jjn j9, dll_r")
        J("jldi j10, 5"); da("j11", D_NC); J("jldi j12, 32", "jcall r_file", "jldi j10, 5"); da("j11", D_MC); J("jldi j12, 32", "jcall r_file", "jldi j10, 5"); da("j11", D_BN0); J("jldi j12, 48", "jcall r_file", "jldi j10, 5"); da("j11", D_PM); J("jldi j12, %d" % (48 + 2048 + 96), "jcall r_file", "jldi j10, 7", "jcall r_file")
        o("dll_r:                          ; (her alphabet: every line of \"abecedario\", a letter)")
        da("j11", D_LBL + 48); J("jldi j12, 10", "jcall r_open"); ld("j9", "FH"); J("jjn j9, dll_ar")
        J("jldi j10, 38", "jldi j11, -1", "jldi j12, 0", "jcall r_file"); ds("j13", D_LFE); J("jldi j10, 38", "jldi j11, 0", "jldi j12, 0", "jcall r_file")
        dl("j1", D_LFE); J("jldi j10, 64", "jadd j1, j1, j10", "jcall r_alloc"); ds("j0", D_LFB)
        J("jldi j10, 5"); dl("j11", D_LFB); dl("j12", D_LFE); J("jcall r_file", "jldi j10, 7", "jcall r_file"); dl("j1", D_LFB); ds("j1", D_LP)
        o("dll_al:")
        dl("j1", D_LP); dl("j2", D_LFB); dl("j10", D_LFE); J("jadd j2, j2, j10", "jsub j10, j1, j2", "jjnn j10, dll_af", "jadd j8, j1, j14")
        o("dll_ae:")
        J("jsub j10, j8, j2", "jjnn j10, dll_aa", "jldb j5, j8, 0", "jldi j10, 1", "jadd j8, j8, j10", "jldi j10, 10", "jsub j10, j5, j10", "jjnz j10, dll_ae")
        o("dll_aa:")
