        o("dll_ar:")
        J("jcall r_bases", "jret")
        o("r_dlg_write:                    ; a line of \"dialogo\": who (j1: 0 \"vos: \", 1 \"luma: \", 2 her silence), then the text at")
        o("                                ; j2 (j3 bytes)")
        J("jldi j10, 0"); ds("j10", D_SCR0); ds("j1", D_LW); ds("j2", D_X); ds("j3", D_X + 8); J("jadd j1, j2, j14", "jadd j2, j3, j14", "jcall r_letra_text"); dl("j1", D_LW); dl("j2", D_X); dl("j3", D_X + 8)
        J("jcall lj_flowback              ; (her thinking steps go: her flow as it was)"); dl("j1", D_LW); dl("j2", D_X); dl("j3", D_X + 8)
        J("jcall lj_answer                ; (a piece of her one answer)"); dl("j1", D_LW); dl("j2", D_X); dl("j3", D_X + 8)
