        o("dw_t:                           ; (the line is written from where it is, never copied: a story of any length fits,")
        o("                                ; and no scratch room of a fixed size runs over onto what lies after it)")
        J("jldi j10, 2", "jsub j10, j1, j10", "jjz j10, dw_ns", "jldi j10, 3", "jsub j10, j1, j10", "jjnz j10, dw_nl")
        o("dw_ns:                          ; (her silence: the words of who, and nothing after them)")
        J("jldi j10, 0"); ds("j10", D_X + 8)
        o("dw_nl:")
        da("j8", D_SCR); J("jsub j7, j7, j8"); ds("j7", D_X + 16)
        o("  ; (NOT A MIRROR, the Capitan, 2026-11-24: \"que no se pierda en el reflejo de un espejo interminable\": her talk with")
        o("  ;  her readings goes to its own file, charla-libros, which is no book of hers; dialogo is theirs alone, his and hers,")
        o("  ;  and a book of her shelf: written there, she would read her own echoes and answer them)")
        o("  ; (HER GREETINGS ARE NOT THEIR TALK (the Capitan, 2026-11-25: \"estoy harto de los logs\"): \"me comí\" goes to its")
        o("  ; own notebook, \"me-comi\"; their talk is a book she answers from, and her notices filled her answers to him)")
        da("j11", D_LBL); J("jldi j12, 7"); ld("j1", "GREET"); J("jjz j1, dw_sf"); li("j11", g["G"]["MCL"]); J("jldi j12, 7", "jjmp dw_op")
        o("dw_sf:")
        ld("j1", "ARR"); J("jjz j1, dw_op", "jld j1, j1, %d" % SF_ON, "jjz j1, dw_op"); da("j11", D_LBL + 144); J("jldi j12, 13")
        o("dw_op:")
        J("jcall r_open"); ld("j9", "FH"); J("jjn j9, dw_r")
        J("jldi j10, 38", "jldi j11, -1", "jldi j12, 0", "jcall r_file", "jldi j10, 6"); da("j11", D_SCR); dl("j12", D_X + 16); J("jcall r_file")
        dl("j12", D_X + 8); J("jjz j12, dw_e", "jldi j10, 6"); dl("j11", D_X + 0); J("jcall r_file")
        o("dw_e:")
        J("jldi j10, 10"); da("j11", D_SCR); J("jstb j10, j11, 0", "jldi j12, 1", "jldi j10, 6", "jcall r_file", "jldi j10, 7", "jcall r_file")
        o("dw_r:")
        J("jret")
        o("r_dlg_words:                    ; the words of more than three letters at j1 (j2 bytes) -> the words said to her")
        J("jadd j10, j1, j2"); gs("j10", BE); gs("j1", BP); J("jldi j10, 0"); ds("j10", D_NW)
        o("dws_l:")
        J("jcall bw_word", "jjz j0, dws_d"); J("jldi j10, 4", "jsub j10, j0, j10", "jjn j10, dws_l")
        dl("j3", D_NW); J("jldi j10, 120", "jsub j10, j3, j10", "jjnn j10, dws_d"); da("j7", D_WORDS); J("jldi j5, 0")
        o("dws_u:                          ; (each word once)")
        J("jsub j10, j5, j3", "jjnn j10, dws_add", "jldi j10, 3", "jshl j10, j5, j10", "jadd j10, j7, j10", "jld j10, j10, 0", "jsub j10, j10, j4", "jjz j10, dws_l",
          "jldi j10, 1", "jadd j5, j5, j10", "jjmp dws_u")
        o("dws_add:")
        J("jldi j10, 3", "jshl j10, j3, j10", "jadd j10, j7, j10", "jst j4, j10, 0", "jldi j10, 1", "jadd j3, j3, j10"); ds("j3", D_NW); J("jjmp dws_l")
        o("dws_d:")
        J("jldi j10, 1", "jadd j1, j1, j10", "jret")
        o("r_dlg_quien:                    ; WHO IT IS, BY ALL IT DOES (see D_SX) -> j0 = 1 with her paragraph in D_OUT, or 0")
