        o("  ; (the subject, and the prints of all he said)")
        st("j14", "BFOR"); J("jldi j10, 0"); ds("j10", D_SXW); ds("j10", D_SX); ds("j10", D_SHN); da("j1", D_RP); gs("j1", BP); da("j2", D_RP); dl("j3", D_RPL); J("jadd j2, j2, j3"); gs("j2", BE)
        o("dq_w:")
        J("jcall bw_word", "jjz j0, dq_wd"); dl("j1", D_SHN); J("jldi j10, 32", "jsub j10, j1, j10", "jjnn j10, dq_w0", "jldi j10, 3", "jshl j2, j1, j10"); da("j3", D_QH); J("jadd j3, j3, j2", "jst j4, j3, 0", "jldi j10, 1", "jadd j1, j1, j10"); ds("j1", D_SHN)
        o("dq_w0:")
        gl("j1", BWS); ds("j1", D_SI); gl("j1", BP); ds("j1", D_SJ); J("jcall r_winfo", "jldi j10, 2", "jsub j10, j2, j10", "jjn j10, dq_w"); dl("j1", D_SXW); J("jsub j10, j0, j1", "jjn j10, dq_w", "jjz j10, dq_w")
        ds("j0", D_SXW); ds("j4", D_SX); dl("j1", D_SI); ds("j1", D_SXT); dl("j2", D_SJ); J("jsub j2, j2, j1"); ds("j2", D_SXTL); J("jjmp dq_w")
        o("dq_wd:")
        dl("j1", D_SX); J("jjz j1, dq_r0"); li("j1", SQ_N * SQ_E + 64); J("jcall r_alloc"); ds("j0", D_SBR); J("jldi j10, %d" % SQ_N); ds("j10", D_SCAP); J("jldi j10, 0"); ds("j10", D_SN); ds("j10", D_SR)
        J("jcall dq_scan")
        o("  ; (her paragraph: the subject as he said it, then up to four things it does, his own next word first, then what her")
        o("  ; books say most; a clause all of whose words he already said is not an answer)")
        dl("j1", D_SN); J("jjz j1, dq_none"); da("j7", D_OUT); dl("j2", D_SXT); dl("j3", D_SXTL); J("jldi j4, 0")
        o("dq_cs:")
