        o("dq_pick:")
        dl("j1", D_SCNT); J("jldi j10, 4", "jsub j10, j1, j10", "jjnn j10, dq_done", "jldi j10, -1"); ds("j10", D_SBK); ds("j10", D_SKY); J("jldi j10, 0"); ds("j10", D_SI)
        o("dq_pl:")
        dl("j1", D_SI); dl("j2", D_SN); J("jsub j10, j1, j2", "jjnn j10, dq_pg", "jldi j10, %d" % SQ_E, "jmul j1, j1, j10"); dl("j2", D_SBR); J("jadd j9, j1, j2", "jld j10, j9, 24", "jjnz j10, dq_pn", "jld j5, j9, 8", "jld j6, j9, 0", "jldi j8, 0")
        dl("j3", D_SHN); da("j4", D_QH)
