        GA = g["G"]
        o("r_pens_launch:                  ; HER THINKER (the Capitan, 2026-11-24: \"que use mas remeros\"; \"no inventes nada, tenemos")
        o("                                ; todo\"): herself in a child, as her reader is, born once with her and asleep on its")
        o("                                ; mailbox (her birth costs a minute: one for each question would be a minute an")
        o("                                ; answer). His questions are thought at once; her own study in the gaps (42). Her dialogue")
        o("                                ; lives there: his questions, her self-talk, her speaking first, her mind. Her body")
        o("                                ; draws, listens and eats, and says what her thinker leaves in \"respuesta\".")
        o("  ; (its initial data: 2 at 20h, \"I am her thinker\")")
        J("jldi j10, 12"); li("j11", GA["PD1"]); J("jldi j12, 20", "jcall r_tocar")
        li("j11", GA["PD1"]); J("jldi j12, 20", "jcall r_open"); ld("j9", "FH"); J("jjn j9, pnl_r")
        J("jldi j1, 48", "jcall r_alloc", "jldi j10, 2", "jst j10, j0, 32", "jadd j11, j0, j14", "jadd j8, j0, j14", "jldi j10, 6", "jldi j12, 40", "jcall r_file", "jldi j10, 7", "jcall r_file")
        J("jldi j10, 3", "jadd j11, j8, j14", "jldi j12, 0", "jcall r_tocar")
        o("  ; (HER SIGNATURE, INHERITED (45, the kernel's \"herencia paterna\"): every file her thinker opens is an important")
        o("  ; request, and each one waited for her body's signature: born alone in 23 s, beside her it took minutes. Her")
        o("  ; next child is signed for all she may sign herself; the kernel cuts it to that, and the porters still decide)")
        li("j12", (1 << 48) - 2); J("jldi j10, 45", "jldi j11, 0", "jcall r_tocar")
        li("j10", 16 | (14 << 32)); li("j11", GA["PB1"]); J("jldi j12, 18", "jcall r_tocar", "jjn j13, pnl_r")
        J("jldi j10, 1", "jadd j1, j13, j10"); st("j1", "PKID"); st("j14", "PBUSY")
        J("jldi j1, 1024", "jcall r_alloc"); st("j0", "PQBUF"); st("j14", "PQLEN")
        o("  ; (born as everyone, not in the gaps: born in the gaps while her body was being born, it took three minutes to")
        o("  ; be ready, and his first question waited them, 2026-11-24. Each task sets its own afterwards: r_pens_say)")
        o("pnl_r:")
        J("jret")
        o("r_pens_say:                     ; j1 = what her thinker does (1 his question, 2 a line of her book, 3 she speaks first),")
        o("                                ; if it is not thinking already")
        ld("j2", "PBUSY"); J("jjnz j2, pns_r", "jldi j2, 1"); st("j2", "PBUSY")
        o("  ; (SELF-ADJUSTING (the Capitan: \"que si el procesador esta desocupado lo ocupe, sin abusar\"): his question is")
        o("  ; thought at once, as everyone; her own study only in the gaps, with what the processor has left)")
        J("jadd j9, j1, j14", "jldi j12, 1", "jldi j10, 1", "jsub j10, j1, j10", "jjnz j10, pns_g", "jldi j12, 0")
        o("pns_g:")
        ld("j11", "PKID"); J("jldi j10, 1", "jsub j11, j11, j10", "jldi j10, 42", "jcall r_tocar")
        ld("j11", "PKID"); J("jldi j10, 1", "jsub j11, j11, j10", "jadd j12, j9, j14", "jldi j10, 30", "jcall r_tocar")
        o("pns_r:")
        J("jret")
        o("r_pens_ask:                     ; Enter: what he typed, to her thinker (as a file, \"pregunta\"); none: she thinks here")
        o("  ; (UNTIL HER THINKER IS READY, ONE OAR DOES BOTH (the Capitan: \"si solo hay un remero, turnarse\"): its birth")
        o("  ; takes a minute or more, and while it was born he was not heard. Her body thinks, as always, until it says 5)")
        ld("j1", "PKID"); J("jjz j1, r_dlg_sent"); ld("j1", "PREADY"); J("jjz j1, r_dlg_sent")
        o("  ; (HIS ENTER IS NEVER LOST (the Capitan, 2026-11-24: \"ahi es cuando el enter deja de funcionar\"): it used to be")
        o("  ; let go while her thinker thought, or was still being born. What he typed leaves his line at once and is shown")
