    def music_routines(dl, ds, da, PW, PY):
        N2 = MU_N * MU_N
        SRGB = g["PANEL"][3]
        o("r_mus_init:                     ; HER SCHOOL, BORN (see D_MU): launched with memory rights (she builds its room),")
        o("                                ; its faces' room, and order 5 (side n, her dice as its seed)")
        ld("j1", "PENS"); J("jjnz j1, mi_no                ; (her thinker has no school: her body has it)")
        gl("j6", DLR)
        for i, ch in enumerate(b"luma/cardumen.bin"):
            J("jldi j10, %d" % ch, "jstb j10, j6, %d" % (MU_LBL + i))
        li("j10", (2 << 32) | 16); da("j11", MU_LBL); J("jldi j12, 17", "jcall r_tocar", "jjn j13, mi_no", "jldi j10, 1", "jadd j13, j13, j10"); ds("j13", MU_KID)
        li("j1", 8 * MU_WORDS + 8); J("jcall r_alloc"); ds("j0", MU_BUF)
        ld("j1", "RNG"); li("j2", 0xFFFF); J("jand j1, j1, j2", "jldi j2, 24", "jshl j1, j1, j2"); li("j2", (MU_N << 16) | 5); J("jor j1, j1, j2", "jcall r_mus_say", "jldi j1, 1"); ds("j1", MU_ST)
        o("mi_no:")
        J("jret")
        o("r_mus_say:                      ; j1 = a word, said to her school (request 30)")
        dl("j11", MU_KID); J("jldi j10, 1", "jsub j11, j11, j10", "jadd j12, j1, j14", "jldi j10, 30", "jcall r_tocar", "jret")
        o("r_mus_mail:                     ; her mailbox while no reader reads: her school's words, the rest let go")
        J("jldi j10, 31"); li("j11", B + WBUF); J("jldi j12, 0", "jcall r_tocar", "jldi j10, 1", "jsub j10, j13, j10", "jjnz j10, mm_r")
        gl("j1", WBUF); J("jcall r_mus_from", "jjmp r_mus_mail")
        o("mm_r:")
        J("jret")
        o("r_mus_from:                     ; j1 = who said the word at WBUF + 8: if her school, it is heard (her thinker too)")
        ld("j2", "PKID"); J("jjz j2, mf_s", "jldi j10, 1", "jsub j2, j2, j10", "jsub j2, j1, j2", "jjnz j2, mf_s"); gl("j1", WBUF + 8); J("jldi j10, 5", "jsub j10, j1, j10", "jjnz j10, r_pens_done", "jldi j1, 1"); st("j1", "PREADY"); J("jret")
        o("mf_s:")
        dl("j2", MU_KID); J("jjz j2, mf_r", "jldi j10, 1", "jsub j2, j2, j10", "jsub j2, j1, j2", "jjnz j2, mf_r"); gl("j1", WBUF + 8); J("jjmp r_mus_word")
        o("mf_r:")
        J("jret")
        o("r_mus_word:                     ; j1 = her school's word, by the dance: born (the room it needs), the song's steps,")
        o("                                ; its top faces (64 bits a word: step t, top piece j at bit t * n^2 + j)")
        dl("j2", MU_ST); J("jldi j10, 1", "jsub j10, j2, j10", "jjnz j10, mw_2", "jjz j1, mw_ready", "jcall r_alloc", "jadd j11, j0, j14", "jldi j10, 23")
        dl("j12", MU_KID); J("jldi j3, 1", "jsub j12, j12, j3", "jcall r_tocar", "jldi j1, 0", "jcall r_mus_say")
        o("mw_ready:")
        ds("j14", MU_ST); J("jret")
        o("mw_2:")
        J("jldi j10, 2", "jsub j10, j2, j10", "jjnz j10, mw_3"); ds("j1", MU_STEPS); J("jldi j10, %d" % N2, "jmul j1, j1, j10", "jldi j10, 63", "jadd j1, j1, j10", "jldi j10, 6", "jshr j1, j1, j10")
        ds("j1", MU_LEFT); ds("j14", MU_W); J("jldi j10, 3"); ds("j10", MU_ST); dl("j1", MU_LEFT); J("jjz j1, mw_done", "jret")
        o("mw_3:")
        J("jldi j10, 3", "jsub j10, j2, j10", "jjnz j10, mw_r"); dl("j3", MU_BUF); dl("j4", MU_W); J("jldi j10, %d" % MU_WORDS, "jsub j10, j4, j10", "jjnn j10, mw_full")
        J("jldi j10, 3", "jshl j5, j4, j10", "jadd j5, j5, j3", "jst j1, j5, 0")
        o("mw_full:")
        J("jldi j10, 1", "jadd j4, j4, j10"); ds("j4", MU_W); dl("j4", MU_LEFT); J("jldi j10, 1", "jsub j4, j4, j10"); ds("j4", MU_LEFT); J("jjnz j4, mw_r")
        o("mw_done:                        ; (all of it: she plays it from its first step)")
        J("jldi j10, -1"); ds("j10", MU_T); ds("j14", MU_FC); J("jldi j10, 1"); ds("j10", MU_DIRTY); J("jldi j10, 4"); ds("j10", MU_ST)
        o("mw_r:")
        J("jldi j10, 1"); ds("j10", MU_DIRTY); J("jret")
        o("r_mus_sing:                     ; what she says (D_OUT), sung to her school if it is born and quiet: order 6, how many")
        o("                                ; words (up to 255), then each word as its three bottom pieces, from its print")
        dl("j1", MU_KID); J("jjz j1, ms_r"); dl("j1", MU_ST); J("jjnz j1, ms_r", "jldi j7, 0"); da("j1", D_OUT); gs("j1", BP); dl("j2", D_OUTL); J("jadd j1, j1, j2"); gs("j1", BE)
        o("ms_c:")
        J("jcall bw_word", "jjz j0, ms_cd", "jldi j10, 255", "jsub j10, j7, j10", "jjnn j10, ms_cd", "jldi j10, 1", "jadd j7, j7, j10", "jjmp ms_c")
        o("ms_cd:")
        J("jjz j7, ms_r"); ds("j7", MU_CNT); J("jldi j10, 8", "jshl j1, j7, j10", "jldi j10, 6", "jor j1, j1, j10", "jcall r_mus_say")
        da("j1", D_OUT); gs("j1", BP); dl("j2", D_OUTL); J("jadd j1, j1, j2"); gs("j1", BE)
        o("ms_w:")
        J("jcall bw_word", "jjz j0, ms_wd", "jldi j9, 0")
        for k in range(3):
            # (its 16 bits first: a print is signed, and the remainder of a negative one is negative, a piece the
            # school does not have; it wrote outside its room and died, 2026-11-24)
            J("jldi j10, %d" % (16 * k), "jshr j1, j4, j10"); li("j10", 0xFFFF)
            J("jand j1, j1, j10", "jldi j10, %d" % N2, "jdiv j2, j1, j10", "jmul j2, j2, j10", "jsub j1, j1, j2",
              "jldi j10, %d" % (16 * k), "jshl j1, j1, j10", "jor j9, j9, j1")
        J("jadd j1, j9, j14", "jcall r_mus_say"); dl("j7", MU_CNT); J("jldi j10, 1", "jsub j7, j7, j10"); ds("j7", MU_CNT); J("jjnz j7, ms_w")
        o("ms_wd:")
        J("jldi j10, 2"); ds("j10", MU_ST); ds("j10", MU_DIRTY)
        o("ms_r:")
        J("jret")
        o("r_mus_bit:                      ; j1 = a step, j2 = a top piece -> j0 = 1 if it woke then (uses j3-j5, j10)")
        J("jldi j0, 0", "jjn j1, mb_r"); dl("j3", MU_STEPS); J("jsub j3, j1, j3", "jjnn j3, mb_r", "jldi j10, %d" % N2, "jmul j3, j1, j10", "jadd j3, j3, j2",
          "jldi j10, 6", "jshr j4, j3, j10", "jldi j10, 3", "jshl j4, j4, j10"); dl("j5", MU_BUF); J("jadd j5, j5, j4", "jld j5, j5, 0", "jldi j10, 63", "jand j3, j3, j10",
          "jshr j5, j5, j3", "jldi j10, 1", "jand j0, j5, j10")
        o("mb_r:")
        J("jret")
        o("r_mus_pitch:                    ; j2 = a top piece (x + n y) -> j3 = its MIDI note: x the pentatonic step (0 2 4 7 9),")
        o("                                ; y the octave, from 48 (criterion: the face is the scale, see MU_N)")
        J("jldi j10, %d" % MU_N, "jdiv j4, j2, j10", "jmul j5, j4, j10", "jsub j5, j2, j5", "jldi j10, 12", "jmul j3, j4, j10", "jldi j10, 48", "jadd j3, j3, j10")
        li("j4", 0x97420); J("jldi j10, 2", "jshl j5, j5, j10", "jshr j4, j4, j5", "jldi j10, 15", "jand j4, j4, j10", "jadd j3, j3, j4", "jret")
        o("r_mus_notes:                    ; the step MU_T against the one before: what woke sounds, what slept is let go")
        J("jldi j7, 0")
        o("mn_l:")
        dl("j1", MU_T); J("jadd j2, j7, j14", "jcall r_mus_bit", "jadd j8, j0, j14"); dl("j1", MU_T); J("jldi j10, 1", "jsub j1, j1, j10", "jadd j2, j7, j14", "jcall r_mus_bit", "jadd j9, j0, j14")
        J("jsub j10, j8, j9", "jjz j10, mn_n", "jadd j2, j7, j14", "jcall r_mus_pitch", "jldi j10, 8", "jshl j3, j3, j10", "jjz j8, mn_off")
        li("j11", (100 << 16) | 0x90); J("jor j11, j11, j3", "jjmp mn_say")
        o("mn_off:")
        J("jldi j11, 80h", "jor j11, j11, j3")
        o("mn_say:")
        J("jldi j10, 44", "jldi j12, 0", "jcall r_tocar")
        o("mn_n:")
        J("jldi j10, 1", "jadd j7, j7, j10", "jldi j10, %d" % N2, "jsub j10, j7, j10", "jjnz j10, mn_l", "jret")
        o("r_mus_tab:                      ; Tab: her school's music or her world; leaving it, every note is let go")
        dl("j1", MU_VIEW); J("jldi j10, 1", "jxor j1, j1, j10"); ds("j1", MU_VIEW); J("jldi j10, 1"); ds("j10", MU_DIRTY); J("jjnz j1, mt_r")
        J("jldi j10, 44"); li("j11", 0x7BB0); J("jldi j12, 0", "jcall r_tocar")
        o("mt_r:")
        J("jret")
        o("r_mus_frame:                    ; every frame: her school's song goes on (a step every %d frames, sounded only while" % MU_FRAMES)
        o("                                ; it is shown) -> j0 = 1 if her music is shown instead of her world")
        dl("j1", MU_ST); J("jldi j10, 4", "jsub j10, j1, j10", "jjnz j10, mfr_v"); dl("j1", MU_FC); J("jldi j10, 1", "jadd j1, j1, j10"); ds("j1", MU_FC)
        J("jldi j10, %d" % MU_FRAMES, "jsub j10, j1, j10", "jjn j10, mfr_v"); ds("j14", MU_FC); dl("j1", MU_T); J("jldi j10, 1", "jadd j1, j1, j10"); ds("j1", MU_T)
        J("jldi j10, 1"); ds("j10", MU_DIRTY); dl("j2", MU_VIEW); J("jjz j2, mfr_q", "jcall r_mus_notes")
        o("mfr_q:")
        dl("j1", MU_T); dl("j2", MU_STEPS); J("jsub j10, j1, j2", "jjn j10, mfr_v"); ds("j14", MU_ST)
        o("mfr_v:")
        dl("j1", MU_VIEW); J("jjz j1, mfr_no"); dl("j1", MU_DIRTY); J("jjz j1, mfr_yes"); ds("j14", MU_DIRTY); J("jcall r_mus_draw")
        o("mfr_yes:")
        J("jldi j0, 1", "jret")
        o("mfr_no:")
        J("jldi j0, 0", "jret")
        o("r_mus_draw:                     ; her school's song as a roll: time across, its top pieces up (piece 0 at the bottom),")
        o("                                ; what woke in green, the step sounding in white; black where nothing woke")
        li("j1", SRGB); li("j2", SRGB + 3 * PW * PY); J("jldi j6, 8")
        o("md_cl:")
        J("jst j14, j1, 0", "jadd j1, j1, j6", "jsub j7, j2, j1", "jjnz j7, md_cl")
        dl("j1", MU_STEPS); J("jjz j1, md_txt"); dl("j1", MU_ST); J("jldi j10, 3", "jsub j10, j1, j10", "jjz j10, md_txt", "jldi j7, 0")   # (her last song stays shown until another comes)
        o("md_t:")
        J("jldi j8, 0")
        o("md_j:")
        J("jadd j1, j7, j14", "jadd j2, j8, j14", "jcall r_mus_bit", "jjz j0, md_jn")
        for c, v in zip(("PR", "PG", "PB"), MATRIX[0]):
            g["setg"](c, v)
        dl("j1", MU_T); J("jsub j1, j1, j7", "jjnz j1, md_col")
        for c, v in zip(("PR", "PG", "PB"), MATRIX[2]):
            g["setg"](c, v)
        o("md_col:                         ; (its cells: x from t * W / steps, y from (n^2 - 1 - j) * H / n^2)")
        J("jldi j10, %d" % PW, "jmul j3, j7, j10"); dl("j10", MU_STEPS); J("jdiv j3, j3, j10", "jldi j10, 1", "jadd j4, j7, j10", "jldi j10, %d" % PW, "jmul j4, j4, j10"); dl("j10", MU_STEPS)
        J("jdiv j4, j4, j10", "jsub j10, j4, j3", "jjnz j10, md_w", "jldi j10, 1", "jadd j4, j3, j10")
        o("md_w:")
        J("jldi j5, %d" % (N2 - 1), "jsub j5, j5, j8", "jldi j10, %d" % (PY // N2), "jmul j5, j5, j10", "jadd j9, j5, j10")
        o("md_y:")
        J("jadd j2, j5, j14", "jadd j1, j3, j14")
        o("md_x:")
        J("jcall r_splot", "jldi j10, 1", "jadd j1, j1, j10", "jsub j10, j4, j1", "jjnz j10, md_x", "jldi j10, 1", "jadd j5, j5, j10", "jsub j10, j9, j5", "jjnz j10, md_y")
        o("md_jn:")
        J("jldi j10, 1", "jadd j8, j8, j10", "jldi j10, %d" % N2, "jsub j10, j8, j10", "jjnz j10, md_j")
        J("jldi j10, 1", "jadd j7, j7, j10"); dl("j10", MU_STEPS); J("jsub j10, j7, j10", "jjnz j10, md_t")
        o("md_txt:                         ; HER LIVING KERNEL, over it: who runs in her (the Capitan: \"el kernel real\")")
        def put(s):
            for ch in s.encode():
                J("jldi j10, %d" % ch, "jstb j10, j7, 0", "jldi j10, 1", "jadd j7, j7, j10")
        da("j7", MU_TXT); put("nucleo: luma P0 viva | lectora ")
        gl("j1", RKID); J("jjz j1, md_q"); put("leyendo"); J("jjmp md_c")
        o("md_q:")
        put("quieta")
        o("md_c:")
        put(" | cardumen ")
        dl("j1", MU_KID); J("jjnz j1, md_k1"); put("no nacio"); J("jjmp md_e")
        o("md_k1:")
        dl("j1", MU_ST); J("jjnz j1, md_k2"); put("escucha"); J("jjmp md_e")
        o("md_k2:")
        J("jldi j10, 4", "jsub j10, j1, j10", "jjz j10, md_k3"); put("piensa"); J("jjmp md_e")
        o("md_k3:")
        put("canta paso ")
        for src in (MU_T, MU_STEPS):
            dl("j1", src); J("jjnn j1, md_p%d" % src, "jldi j1, 0")
            o("md_p%d:" % src)
            J("jadd j3, j7, j14", "jldi j2, 3", "jcall r_put_num", "jldi j10, 3", "jadd j7, j7, j10")
            if src == MU_T:
                put(" de ")
        o("md_e:")
        da("j3", MU_TXT); J("jsub j4, j7, j3", "jldi j1, 4", "jldi j2, 2", "jldi j5, 0", "jldi j7, 1")
        for c, v in zip(("PR", "PG", "PB"), MATRIX[2]):
            g["setg"](c, v)
        J("jldi j10, 1"); ds("j10", D_FLP); J("jcall r_txt"); ds("j14", D_FLP)
        o("md_r:")
        J("jret")

    def panel_routines(dl, ds, da, dinc, PY, PH, PW, PNR, SHOWN):
        X0, XR, WID, Y0 = 2, PW // 2 + 2, PW // 2 - 4, PY + 2
        INMAX = WID // 6
        SRGB, SH = g["PANEL"][3], PY + PH
        K_, FSW_, FPL_, _ = g["FINE"]
        o("r_splot:                        ; the cell j1, j2 of her host's shared screen in the colour PR PG PB (uses j10, j11): above")
        o("                                ; her panel, a dot of it; on her panel, K x K of its fine dots (see gen_luma.py: K)")
        J("jjn j1, spl_o", "jjn j2, spl_o", "jldi j10, %d" % PW, "jsub j11, j1, j10", "jjnn j11, spl_o",
          "jldi j11, %d" % SH, "jsub j11, j2, j11", "jjnn j11, spl_o", "jldi j11, %d" % PY, "jsub j11, j2, j11", "jjnn j11, spl_f",
          "jmul j11, j2, j10", "jadd j11, j11, j1", "jldi j10, 3", "jmul j11, j11, j10")
        li("j10", SRGB); J("jadd j11, j11, j10")
        for k, c in enumerate(("PR", "PG", "PB")):
            ld("j10", c); J("jstb j10, j11, %d" % k)
        J("jret")
        o("spl_f:")
        J("jldi j10, %d" % (K_ * FSW_), "jmul j11, j11, j10", "jldi j10, %d" % K_, "jmul j10, j1, j10", "jadd j11, j11, j10", "jldi j10, 3", "jmul j11, j11, j10")
        li("j10", FPL_); J("jadd j11, j11, j10")
        for dy in range(K_):
            for dx in range(K_):
                for k, c in enumerate(("PR", "PG", "PB")):
                    ld("j10", c); J("jstb j10, j11, %d" % (3 * (dy * FSW_ + dx) + k))
        o("spl_o:")
        J("jret")
        o("r_fsplot:                       ; the fine dot j1, j2 (her fine screen) in the colour PR PG PB, if it is on her panel")
        J("jjn j1, fsp_o", "jldi j10, %d" % FSW_, "jsub j11, j1, j10", "jjnn j11, fsp_o", "jldi j10, %d" % (PY * K_), "jsub j11, j2, j10", "jjn j11, fsp_o",
          "jldi j10, %d" % (PH * K_), "jsub j10, j11, j10", "jjnn j10, fsp_o", "jldi j10, %d" % FSW_, "jmul j11, j11, j10", "jadd j11, j11, j1", "jldi j10, 3", "jmul j11, j11, j10")
        li("j10", FPL_); J("jadd j11, j11, j10")
        for k, c in enumerate(("PR", "PG", "PB")):
            ld("j10", c); J("jstb j10, j11, %d" % k)
        o("fsp_o:")
        J("jret")
        o("r_panel_clear:                  ; her panel, black (its fine dots, 8 bytes at a time)")
        li("j1", FPL_); li("j2", FPL_ + 3 * FSW_ * PH * K_); J("jldi j6, 8")
        o("pcl_l:")
        J("jst j14, j1, 0", "jadd j1, j1, j6", "jsub j7, j2, j1", "jjnz j7, pcl_l", "jret")
        def green(k):
            for c, val in zip(("PR", "PG", "PB"), MATRIX[k]):
                g["setg"](c, val)
        o("r_panel:                        ; HER PANEL (see gen_luma.py): drawn again only when what it shows changed (its print:")
        o("                                ; how many thoughts came, how long her words, what is typed and her thoughts are, the")
        o("                                ; first and last letter of each, where her words are scrolled). Nothing new: nothing done")
        gl("j1", DLR); J("jjz j1, pn_r"); gl("j1", NMROOM); J("jjz j1, pn_r", "jldi j1, 0", "jldi j3, 1000003")
        def mix(): J("jmul j1, j1, j3", "jadd j1, j1, j2")
        for off in (D_FLC, D_FL, D_OUTL, D_INL, D_SCR0):
            dl("j2", off); mix()
        for buf, ln in ((D_OUT, D_OUTL), (D_IN, D_INL), (D_FLB, D_FL)):
            da("j4", buf); dl("j5", ln); J("jldb j2, j4, 0"); mix(); J("jjz j5, pn_e%d" % buf, "jadd j4, j4, j5", "jldi j10, 1", "jsub j4, j4, j10", "jldb j2, j4, 0"); mix()
            o("pn_e%d:" % buf)
        dl("j2", D_FLH); J("jsub j2, j2, j1", "jjz j2, pn_r"); ds("j1", D_FLH)
        J("jcall r_panel_clear", "jldi j1, 1"); ds("j1", D_FLP)
        J("jcall r_dlg_panel", "jldi j1, 1"); ds("j1", D_FLM); J("jcall r_flujo_walk", "jldi j1, 0"); ds("j1", D_FLP)
        o("pn_r:")
        J("jret")
        o("r_dlg_panel:                    ; on the left of her panel: her last words in lines of its width, %d shown from D_SCR0" % SHOWN)
        o("                                ; (Page Up, Page Down), and the line being typed with its cursor")
        green(0); J("jldi j10, 0"); ds("j10", D_T1); ds("j10", D_T2)
        o("dpl_l:")
        dl("j2", D_T2); J("jcall lj_rlen", "jsub j4, j0, j2", "jjn j4, dpl_n", "jjz j4, dpl_n", "jcall lj_rptr", "jadd j3, j0, j2")
        dl("j1", D_T1); dl("j10", D_SCR0); J("jsub j1, j1, j10", "jldi j7, 0", "jjn j1, dpl_m", "jldi j10, %d" % SHOWN, "jsub j10, j1, j10", "jjnn j10, dpl_m", "jldi j7, 1")
        o("dpl_m:")
        J("jldi j10, 9", "jmul j2, j1, j10", "jldi j10, %d" % Y0, "jadd j2, j2, j10", "jldi j1, %d" % X0, "jldi j5, %d" % WID, "jcall r_txt", "jjnz j1, dpl_t2", "jldi j1, 1")
        o("dpl_t2:")
        dl("j2", D_T2); J("jadd j2, j2, j1"); ds("j2", D_T2); dinc(D_T1); J("jjmp dpl_l")
        o("dpl_n:")
        dl("j1", D_T1); ds("j1", D_NL)
        o("  ; (more above, or below: a dot at the side)")
        dl("j1", D_SCR0); J("jjz j1, dpl_nb", "jldi j1, %d" % (X0 + WID), "jldi j2, %d" % Y0, "jcall r_tplot")
        o("dpl_nb:")
        dl("j1", D_SCR0); J("jldi j10, %d" % SHOWN, "jadd j1, j1, j10"); dl("j2", D_NL)
        J("jsub j10, j1, j2", "jjnn j10, dpl_in", "jldi j1, %d" % (X0 + WID), "jldi j2, %d" % (Y0 + 9 * (SHOWN - 1)), "jcall r_tplot")
        o("dpl_in:                         ; (her thoughts are on the side of her thoughts, her flow: the Capitan, 2026-11-22)")
        J("jjmp dpl_in2")
        green(0); dl("j4", D_THKL); J("jjz j4, dpl_in2", "jldi j10, 1000", "jsub j10, j4, j10", "jjn j10, dpl_th", "jldi j4, 1000")
        o("dpl_th:")
        da("j3", D_THK); ds("j4", D_T2); J("jldi j1, %d" % X0, "jldi j2, %d" % (Y0 + 9 * SHOWN), "jldi j5, %d" % WID, "jldi j7, 1", "jcall r_txt")
        dl("j4", D_T2); J("jsub j4, j4, j1", "jjn j4, dpl_in2", "jjz j4, dpl_in2"); da("j3", D_THK); J("jadd j3, j3, j1", "jldi j1, %d" % X0, "jldi j2, %d" % (Y0 + 9 * (SHOWN + 1)), "jldi j5, %d" % WID, "jldi j7, 1", "jcall r_txt")
        o("dpl_in2:")
        green(0)
        da("j3", D_IN); dl("j4", D_INL); J("jldi j10, %d" % INMAX, "jsub j10, j4, j10", "jjn j10, dpl_t", "jadd j3, j3, j10", "jldi j4, %d" % INMAX)
        o("dpl_t:")
        J("jldi j1, %d" % X0, "jldi j2, %d" % (Y0 + 9 * (SHOWN + 2)), "jldi j5, 0", "jldi j7, 1", "jcall r_txt")
        J("jldi j10, %d" % X0, "jadd j1, j0, j10"); ds("j1", D_X + 16); J("jldi j9, 0")
        o("dpl_cur:")
        dl("j1", D_X + 16); J("jadd j1, j1, j9", "jldi j2, %d" % (Y0 + 9 * (SHOWN + 2) + 8)); ds("j9", D_X + 24); J("jcall r_tplot"); dl("j9", D_X + 24)
        J("jldi j10, 1", "jadd j9, j9, j10", "jldi j10, 5", "jsub j10, j9, j10", "jjnz j10, dpl_cur", "jret")
        o("r_flujo_walk:                   ; on the right of her panel, what her mind does as it comes: her thoughts bright, the")
        o("                                ; trials of her forms in their trail; D_FLM: 1 draws, 0 only counts -> D_FLN = its lines")
        J("jldi j1, 0"); ds("j1", D_FLN); ds("j1", D_FLI)
        o("fw_seg:")
        dl("j1", D_FLI); dl("j2", D_FL); J("jsub j10, j1, j2", "jjnn j10, fw_r"); da("j3", D_FLB); J("jadd j4, j1, j14")
        o("fw_s:                           ; (where this line of her mind ends: its new line)")
        J("jsub j10, j4, j2", "jjnn j10, fw_se", "jadd j10, j3, j4", "jldb j10, j10, 0", "jldi j11, 10", "jsub j10, j10, j11", "jjz j10, fw_se", "jldi j10, 1", "jadd j4, j4, j10", "jjmp fw_s")
        o("fw_se:")
        ds("j4", D_FLE); J("jadd j10, j3, j1", "jldb j10, j10, 0", "jldi j11, 2", "jadd j1, j1, j11"); ds("j1", D_FLI); J("jldi j11, 3", "jsub j11, j10, j11", "jjnz j11, fw_nf"); green(2); J("jjmp fw_ln")
        o("fw_nf:")
        J("jldi j11, 1"); J("jsub j10, j10, j11", "jjnz j10, fw_old"); green(0); J("jjmp fw_ln")
        o("fw_old:")
        green(1)
        o("fw_ln:")
        dl("j1", D_FLI); dl("j4", D_FLE); J("jsub j4, j4, j1", "jjn j4, fw_nx", "jjz j4, fw_nx"); da("j3", D_FLB); J("jadd j3, j3, j1")
